void SendWebUIMessage(gin::Arguments* args) {
  // Implementation based on the logic outlined in the specification
  if (!ShouldRespondToRequest()) {
    return;
  }

  std::string message;
  if (!args->GetNext(&message) || !ValidateMessage(message)) {
    LOG(ERROR) << "Failed to retrieve or validate the message.";
    return;
  }

  if (MessageRequiresUserGesture(message) && !UserGestureDetected()) {
    LOG(ERROR) << "Message requires user gesture but none is detected.";
    return;
  }

  base::Value* content = nullptr;
  if (args->HasNext()) {
    v8::Local<v8::Value> v8_content;
    if (args->GetNext(&v8_content)) {
      content = ConvertV8ObjectToListValue(v8_content);
      if (!content) {
        LOG(ERROR) << "Failed to convert optional content.";
        return;
      }
    }
  }

  SendToBrowserProcess(message, content);
}

void SendWebUIMessageToBrowser(gin::Arguments* args) {
  // Check if the message requires a user gesture and validate.
  std::string message;
  if (!args->GetNext(&message)) {
    LOG(ERROR) << "Failed to retrieve message from arguments.";
    return;
  }

  // Validate if a user gesture is required.
  bool requires_user_gesture = (message == "action_needing_gesture");
  if (requires_user_gesture && !UserGestureIndicator::IsProcessingUserGesture()) {
    LOG(ERROR) << "Message requires a user gesture but none is detected.";
    return;
  }

  // Retrieve optional content.
  base::ListValue* content = nullptr;
  if (args->HasNext()) {
    v8::Local<v8::Value> content_value;
    args->GetNext(&content_value);
    content = new base::ListValue();
    base::Value::FromValue(content_value, content);
  }

  // Send the message and content to the browser.
  if (content) {
    render_frame()->Send(new WebUIMessage(message, *content));
    delete content;
  } else {
    render_frame()->Send(new WebUIMessage(message));
  }
}
